### 📌 **1. Inactivity Tracker (Real-Time Activity Monitoring)**

#### ✅ **Implementation Strategy**
Use a lightweight event listener system to detect user activity across:
- Mouse movement (`mousemove`)
- Keyboard input (`keydown`, `keypress`)
- Clicks (`click`)
- API calls (via Axios interceptors or fetch wrapper)

#### ✅ **Code Snippet: Activity Tracker Module**
```js
// src/utils/activityTracker.js
class InactivityTracker {
  constructor(timeoutMinutes = 1440) {
    this.timeoutMs = timeoutMinutes * 60 * 1000;
    this.timer = null;
    this.resetTimer = this.resetTimer.bind(this);
    this.start = this.start.bind(this);
    this.stop = this.stop.bind(this);
    this.handleActivity = this.handleActivity.bind(this);
  }

  start() {
    // Reset timer on any interaction
    document.addEventListener('mousemove', this.handleActivity);
    document.addEventListener('keydown', this.handleActivity);
    document.addEventListener('click', this.handleActivity);

    // Optional: Track API calls via interceptor
    this.setupApiInterceptor();

    // Initialize timer
    this.resetTimer();
  }

  stop() {
    if (this.timer) clearTimeout(this.timer);
    document.removeEventListener('mousemove', this.handleActivity);
    document.removeEventListener('keydown', this.handleActivity);
    document.removeEventListener('click', this.handleActivity);
  }

  handleActivity() {
    this.resetTimer();
  }

  resetTimer() {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.onTimeout();
    }, this.timeoutMs);
  }

  onTimeout() {
    console.log('[Session] Inactivity timeout triggered.');
    this.clearSessionAndRedirect();
  }

  setupApiInterceptor() {
    // Example using Axios
    const instance = axios.create();
    instance.interceptors.response.use(
      response => {
        this.handleActivity(); // Reset on every successful API call
        return response;
      },
      error => {
        this.handleActivity(); // Reset even on errors
        return Promise.reject(error);
      }
    );
  }

  clearSessionAndRedirect() {
    // Clear local/session storage
    localStorage.removeItem('authToken');
    sessionStorage.clear();

    // Optionally: send logout signal to backend (if not already done)
    this.sendLogoutSignal();

    // Redirect to login
    window.location.href = '/login';
  }

  sendLogoutSignal() {
    // Send POST /logout to invalidate session server-side
    fetch('/api/logout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ reason: 'inactivity_timeout' }),
      credentials: 'include' // Ensure cookies are sent
    }).catch(err => {
      console.warn('Failed to notify server of logout:', err);
    });
  }
}

// Export singleton instance
export const activityTracker = new InactivityTracker(1440);
```

