### 🔐 **Session Revocation Strategy: Finalized Pattern**

#### ✅ **Chosen Architecture: JWT + Redis Blacklist (Centralized Token Revocation)**
- **Why?**  
  - JWTs are stateless but need revocation support.
  - Redis provides fast lookup for blacklisted tokens.
  - Supports immediate logout invalidation (`SESS-EXP-1440MIN`).

#### ✅ **Implementation (A2 Backend)**

```js
// === Session Management: JWT + Redis Blacklist ===
const jwt = require('jsonwebtoken');
const redis = require('redis').createClient();

// Generate session token
function generateSessionToken(userId) {
  const payload = { userId };
  const token = jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn: '24h',
  });
  return token;
}

// On Logout: Add to Redis blacklist
app.post('/logout', async (req, res) => {
  const authHeader = req.headers.authorization;
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'No token provided' });

  // Store token in Redis with 24h TTL (covers inactivity expiry)
  await redis.setex(`blacklisted:${token}`, 1440 * 60, 'true'); // 24h expiry

  res.json({ message: 'Logged out successfully' });
});

// Middleware: Check if token is revoked
function authenticateToken(req, res, next) {
  const authHeader = req.headers.authorization;
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Access denied' });

  // Check Redis blacklist first
  redis.get(`blacklisted:${token}`, (err, result) => {
    if (err) throw err;
    if (result === 'true') {
      return res.status(401).json({ error: 'Token has been invalidated' });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) return res.status(403).json({ error: 'Invalid token' });
      req.user = user;
      next();
    });
  });
}
```

> ✅ **Key Features**:
> - Immediate logout invalidation via Redis.
> - Inactivity expiry enforced by JWT `expiresIn: '24h'`.
> - No need to store session data on the server beyond the blacklist.

