  // Store token in Redis with 24h TTL (covers inactivity expiry)
  await redis.setex(`blacklisted:${token}`, 1440 * 60, 'true'); // 24h expiry

  res.json({ message: 'Logged out successfully' });
});

// Middleware: Check if token is revoked
function authenticateToken(req, res, next) {
  const authHeader = req.headers.authorization;
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Access denied' });

  // Check Redis blacklist first
  redis.get(`blacklisted:${token}`, (err, result) => {
    if (err) throw err;
    if (result === 'true') {
      return res.status(401).json({ error: 'Token has been invalidated' });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) return res.status(403).json({ error: 'Invalid token' });
      req.user = user;
      next();
    });
  });
}
```

